if(tab==='More')return `<div class="worker-more"><p>Advanced worker details</p><div class="system-groups">${[['Memory','Memory'],['Files','Files'],['Capabilities','Capabilities'],['Audits','Audits'],['Permissions','Permissions'],['Configuration','Settings'],['History','History'],['Schedules','Schedule']].map(([label,key])=>`<a class="system-link" href="#agents/${encodeURIComponent(record)}/${encodeURIComponent(key)}">${label}</a>`).join('')}</div><p class="hint">These views use the same worker identity and Glacier permission records.</p></div>`;
if(tab==='Chat'){const d=await api('messages',{worker});return panel('Worker conversation',`<p class="hint">Public messages only. Simultaneous chat during a running turn is rejected. Reset preserves memory/history.</p>${details(d.boundaries,'Context boundaries ('+d.boundaries.length+')')}<div id="messages">${messagesHtml(d.messages)}</div>${form('chat-form',area('text','Message to '+w.name,'','required maxlength="20000"'),'Send message')}`);}
