 if($('#dialog').open)return;
 if(e.key==='Enter'&&e.target?.closest?.('#assistant-chat')&&!e.shiftKey){e.preventDefault();e.target.closest('#assistant-chat').requestSubmit();}if(e.key==='F6'){e.preventDefault();const zones=[$('#nav a[aria-current]'),$('#main'),$('#taskbar a[aria-current]')];const current=zones.findIndex(z=>z===document.activeElement||z?.contains(document.activeElement));zones[(current+(e.shiftKey?2:1))%3]?.focus();}
