function gStatus(){const el=$('#graph-draft-state');if(el){el.textContent=ge.run?'RUN '+ge.run.id+' / '+ge.run.state+' / immutable '+ge.run.version_id:(ge.dirty?'UNSAVED DRAFT':'SAVED DRAFT')+' / revision '+ge.env.revision+' / '+(ge.env.head||'not published');el.title=el.textContent;}const nodes=$('.environment-canvas');if(nodes)nodes.innerHTML=gGraph().nodes.map(n=>details(n,n.id+' / '+n.kind)).join('');const versions=$('#graph-versions');if(versions)versions.innerHTML=(ge.env.versions||[]).map(v=>`<p>${esc(v.id)}<small>revision ${esc(v.revision)}</small></p>`).join('')||empty('No published versions');if(ge.run){const s=$('#graph-run');if(s&&![...s.options].some(o=>o.value===ge.run.id)){const o=document.createElement('option');o.value=ge.run.id;o.textContent=ge.run.state+' / '+ge.run.id;s.append(o);s.value=ge.run.id;}if(s){const o=[...s.options].find(o=>o.value===ge.run.id);if(o)o.textContent=ge.run.state+' / '+ge.run.id;}}}
