function gParseConfig(n,f){switch(n.kind){case 'AI_TASK':return {objective:f.objective};case 'TOOL_OPERATION':return {capability:f.capability,arguments:JSON.parse(f.arguments)};case 'TRANSFORM':return {op:f.op,...(f.op==='CONST'?{value:JSON.parse(f.value)}:f.op==='PICK'?{key:f.key}:{})};case 'CONDITION':return {value:f.value==='true'};case 'WAIT':return {until:f.until};case 'CHILD_ENVIRONMENT':return {version:f.version};case 'HUMAN_GATE':return {task:f.task,tool_call_id:f.tool_call_id};case 'CHECKPOINT':return {kind:f.kind,files:JSON.parse(f.files)};case 'GUARDIAN':return {plan:JSON.parse(f.plan)};default:return {};}}
async function gWorker(id,workerId,ticket){const view=generation,mount=$('#graph-worker');try{const [w,perms]=await Promise.all([api('worker',{worker:workerId}),api('permissions',{worker:workerId})]);if(view!==generation||ticket!==ge.inspectorRequest||ge.selected!==id||!mount?.isConnected)return;mount.innerHTML=`<div class="inspector-identity">${workerPortrait(w)}<div><strong>${esc(w.name)}</strong>${badge(w.status)}</div></div>`+`<p>Identity: ${esc(w.id)} / ${esc(w.role)}</p><p>Configured runtime: ${esc(w.configuration.runtime.provider)} / ${esc(w.configuration.runtime.model)}</p>`+details(w.inspection,'Actual task / session / worktree')+details(perms,'Current authority — read only')+details(w.audit_policy,'Supervision')+details(w.configuration.runtime,'Configured brain / parameters');}catch(e){if(view===generation&&ticket===ge.inspectorRequest&&!e.obsolete&&mount?.isConnected)mount.innerHTML=empty(e.message);}}
