function gPos(id){let all={};try{all=JSON.parse(localStorage.getItem('glacier-layout-'+ge.env.id)||'{}')}catch{}const i=gGraph().nodes.findIndex(n=>n.id===id);return all[id]||{x:30+(i%3)*250,y:30+Math.floor(i/3)*170};}
