  const occurrence=developmentOccurrence(context.blueprint_id),target=$('#graph-evidence');
  target.textContent='Reconciling saved occurrence '+occurrence+'…';
  const b=await api('environment.development.inspect',identity);
  if(view!==generation||ge.env.id!==envId)return;
  const prior=b.prepared.runs.find(r=>r.occurrence===occurrence);
  const value=prior?{blueprint:b,receipt:prior,duplicate:true}:await api('environment.development.run',{...identity,occurrence});
