 if(a==='draft'){ge.run=null;ge.runGraph=null;ge.selected=null;ge.selection.clear();ge.inspectorRequest++;$('#graph-inspector').innerHTML=panel('Node Inspector',empty('Select a draft node'));gDraw();gTerminal();notify('Draft view; admitted version unchanged');return;}
 if(a==='save'){const versions=ge.env.versions,snapshot=structuredClone(ge.graph);const saved=await api('environment.save',{id:ge.env.id,name:ge.env.name,graph:snapshot,expected_revision:ge.env.revision});const changed=JSON.stringify(ge.graph)!==JSON.stringify(snapshot);ge.env={...saved,versions};if(!changed){ge.graph=structuredClone(saved.draft);ge.dirty=false;localStorage.removeItem('glacier-unsaved-'+ge.env.id);}else gDirty();gDraw();notify('SUCCESS / canonical revision '+saved.revision+(changed?' / newer edits remain UNSAVED':''));return;}
