 if(a==='delete'){if(!ge.selection.size)throw Error('Select a node.');const ids=new Set(ge.selection);ge.graph.nodes=ge.graph.nodes.filter(n=>!ids.has(n.id));const edges=ge.graph.connections.filter(e=>ids.has(e.source));for(const e of edges)delete ge.graph.nodes.find(n=>n.id===e.target)?.inputs[e.port];ge.graph.connections=ge.graph.connections.filter(e=>!ids.has(e.source)&&!ids.has(e.target));ge.selected=null;ge.selection.clear();ge.inspectorRequest++;gDirty();$('#graph-inspector').innerHTML=empty('Select a node');gDraw();notify('UNSAVED / selected nodes removed');return;}
