function ownerContractPanel(){
 return panel('Owner acceptance contract', '<p>All eighteen requirements remain unaccepted. Preview the exact source contract and select only unexecuted pending work to migrate.</p>'+
 btn('Preview owner contract','owner-contract')+btn('Select current work item','objective-select')+btn('Create current work','owner-new-work'));
}
async function openOwnerContract(){
 const view=generation,caller=ASSISTANT_ID,context=objectiveCallerIdentity(),openingRoute=location.hash;
 modal('Owner contract — candidate definition','<p id="owner-contract-loading">Loading canonical contract…</p>');
 const openingDialog=$('#dialog'),loading=$('#owner-contract-loading');
 let openingClosed=false;
 const dismissOpening=()=>{openingClosed=true;};
 for(const event of ['close','cancel','modalreplace'])openingDialog.addEventListener(event,dismissOpening,{once:true});
 const openingActive=()=>!openingClosed&&view===generation&&location.hash===openingRoute&&caller===ASSISTANT_ID&&context===objectiveCallerIdentity()&&openingDialog.open&&loading.isConnected;
 let initial;
 try{initial=await api('objective.contract.preview',{id:'glacier-completion-selfhosting',selected:[]});}
 catch(e){if(openingActive())reportError(e);return;}
 if(!openingActive())return;
 modal('Owner contract — candidate definition',form('owner-contract-preview',
  area('selected','Explicit pending item IDs to migrate (JSON array)','[]')+
  field('command_id','Stable owner commit command','owner-contract-'+crypto.randomUUID(),'text','required')+
  '<p>No work is selected automatically. Unselected work becomes historical; every requirement stays visibly unsatisfied.</p>'+
  '<div id="owner-contract-result">'+details(initial,'All criteria, provenance and revision continuity')+'</div>',
  'Preview exact migration')+btn('Commit displayed revision','owner-contract-commit','disabled'));
 const el=$('#owner-contract-preview'),target=$('#owner-contract-result');
 const commit=$('#dialog-body [data-action=owner-contract-commit]'),dialog=$('#dialog');
 const routeIdentity=location.hash;
 let displayed=null,epoch=0,committing=false;
 const identity=()=>JSON.stringify(Array.from(new FormData(el).entries()));
 const active=()=>view===generation&&caller===ASSISTANT_ID&&context===objectiveCallerIdentity()&&location.hash===routeIdentity&&dialog.open&&el.isConnected&&$('#owner-contract-preview')===el;
 const current=(requestEpoch,intent)=>active()&&requestEpoch===epoch&&intent===identity();
 const invalidate=()=>{
  epoch++;displayed=null;commit.disabled=true;
  if(el.isConnected){target.textContent='Changed input; preview again before committing.';$('#dialog-error')?.remove();}
 };
 el.addEventListener('input',invalidate);
 el.addEventListener('change',invalidate);
 dialog.addEventListener('close',invalidate,{once:true});
 dialog.addEventListener('cancel',invalidate,{once:true});
 dialog.addEventListener('modalreplace',invalidate,{once:true});
 const requestFor=(value,command)=>value.definition ? {
  id:value.id,command_id:command,expected_revision:value.expected_revision,expected_sequence:value.expected_sequence,
  selected:[...value.selected],preview_hash:value.preview_hash,proposed_definition_hash:value.proposed_definition_hash,
  definition_mode:'CANONICAL_DRAFT'
 } : {id:value.id,command_id:command,preview:value};
 const showPreview=value=>{target.innerHTML=details(value,'Exact owner preview').replace('<details>','<details open>');};
 bindForm('owner-contract-preview',async f=>{
  if(!active()||committing)return;
  const requestEpoch=++epoch,intent=identity();
  displayed=null;commit.disabled=true;
  target.textContent='Loading exact preview…';$('#dialog-error')?.remove();
  try{
   const value=await api('objective.contract.preview',{id:initial.id,selected:JSON.parse(f.selected)});
   if(!current(requestEpoch,intent))return;
   const request=requestFor(value,f.command_id);
   const previous=JSON.parse(localStorage.getItem('glacier-owner-contract-pending')||'null');
   if(previous){
    const oldRequest=previous.format==='owner-contract-reference-v1'?previous.request:previous;
    if(oldRequest.command_id===f.command_id&&JSON.stringify(oldRequest)!==JSON.stringify(request))
     throw Error('Saved command has a different intent; review its exact retry or enter a new command ID.');
   }
   displayed={preview:JSON.parse(JSON.stringify(value)),request,command:f.command_id,epoch:requestEpoch,intent};
   showPreview(displayed.preview);
   commit.disabled=!value.committable;
   localStorage.setItem('glacier-owner-contract-pending',JSON.stringify(request.definition_mode ?
    {format:'owner-contract-reference-v1',request,preview:displayed.preview}:request));
  }catch(e){
   if(!current(requestEpoch,intent))return;
   target.textContent='ERROR: '+e.message;reportError(e);
  }
 });
 commit.onclick=async()=>{
  if(committing||!displayed?.preview.committable||!current(displayed.epoch,displayed.intent)){commit.disabled=true;return;}
  // Capture both the displayed preview and its owner intent once, before awaiting.
  const snapshot=JSON.parse(JSON.stringify(displayed));
  const payload=snapshot.request;
  committing=true;commit.disabled=true;
  try{
   const receipt=await api(payload.definition_mode?'objective.contract.commit_reference':'objective.contract.commit',payload);
   if(!current(snapshot.epoch,snapshot.intent))return;
   clearObjectiveSelection();target.innerHTML=details(receipt,'Immutable migration receipt').replace('<details>','<details open>');
   displayed=null;
  }catch(e){
   if(!current(snapshot.epoch,snapshot.intent))return;
   showPreview(snapshot.preview);
   const error=document.createElement('p');error.textContent='ERROR: '+e.message;target.prepend(error);
   reportError(e);
  }finally{
   committing=false;
   commit.disabled=!(displayed?.preview.committable&&current(displayed.epoch,displayed.intent));
  }
 };
 const saved=localStorage.getItem('glacier-owner-contract-pending');
 if(saved){
  const retry=document.createElement('button');retry.type='button';retry.textContent='Review exact saved owner command';retry.dataset.action='owner-contract-retry';
  $('#dialog-body').append(retry);
  retry.onclick=()=>{
   if(!active()||committing)return;
   try{
    const payload=JSON.parse(saved);
    invalidate();
    el.elements.selected.value=JSON.stringify(payload.preview.selected);
    const request=payload.format==='owner-contract-reference-v1'?payload.request:payload;
    if(payload.format&&payload.format!=='owner-contract-reference-v1')throw Error('Unknown saved owner command format');
    if(payload.format&&JSON.stringify(requestFor(payload.preview,request.command_id))!==JSON.stringify(request))
     throw Error('Saved reference does not match its displayed provenance');
    el.elements.command_id.value=request.command_id;
    displayed={preview:payload.preview,request,command:request.command_id,epoch,intent:identity()};
    showPreview(displayed.preview);
    commit.disabled=!displayed.preview.committable;
   }catch(e){invalidate();target.textContent='ERROR: '+e.message;reportError(e);}
  };
 }
}

async function openOwnerNewWork(){
 const view=generation,caller=ASSISTANT_ID,context=objectiveCallerIdentity(),routeIdentity=location.hash;
 modal('Create current work','<p id="owner-work-loading">Loading current requirements and history…</p>');
 const dialog=$('#dialog'),loading=$('#owner-work-loading'),listeners=new AbortController();
 let el=null,closed=false,epoch=0,displayed=null,committing=false;
 const active=()=>!closed&&view===generation&&caller===ASSISTANT_ID&&context===objectiveCallerIdentity()&&
  location.hash===routeIdentity&&dialog.open&&(el?el.isConnected&&$('#owner-work-form')===el:loading.isConnected);
 const dismiss=()=>{closed=true;epoch++;displayed=null;listeners.abort();};
 for(const event of ['close','cancel','modalreplace'])dialog.addEventListener(event,dismiss,{signal:listeners.signal});
 window.addEventListener('hashchange',dismiss,{signal:listeners.signal});
 for(const event of ['input','change'])$('#assistant-action-scope')?.addEventListener(event,dismiss,{signal:listeners.signal});
 try{
  const value=await api('objective.inspect'),head=value.objective;
  if(!active())return;
  const requirements=head.definition.requirements;
  $('#dialog-body').innerHTML=form('owner-work-form',
   select('requirement','Current requirement',[['','Choose explicitly'],...requirements.map(r=>[r.id,r.id])],'','required')+
   field('work_key','Stable work key','','text','required maxlength="80" pattern="[A-Za-z0-9_.:-]+"')+
   area('rationale','Reason for this new allocation','','required maxlength="2000"')+
   field('budget','Separate new budget','','number','required min="1" max="10" step="1"')+
   field('command_id','Stable owner command','','text','required maxlength="100"')+
   select('predecessor','Optional historical predecessor',[['','No predecessor']])+
   '<p>Creates queued work only. Authorization, selection and dispatch are separate. Historical budgets stay unchanged.</p>'+
   '<div id="owner-work-context"></div><div id="owner-work-result" role="status">Preview required. authority_granted: false; accepted: false.</div>',
   'Preview current work')+btn('Commit displayed work','owner-work-commit','disabled')+
   btn('Review exact saved work command','owner-work-retry');
  el=$('#owner-work-form');
  const target=$('#owner-work-result'),commit=$('[data-action=owner-work-commit]');
  const identity=()=>JSON.stringify(Array.from(new FormData(el).entries()));
  const current=(n,intent)=>active()&&epoch===n&&identity()===intent;
  const invalidate=()=>{epoch++;displayed=null;commit.disabled=true;target.textContent='Changed input; preview again.';$('#dialog-error')?.remove();};
  const show=value=>{target.innerHTML=details(value,'Exact work intent, criteria, frontier and history').replace('<details>','<details open>');};
  const contextFor=()=>{
   const req=requirements.find(r=>r.id===el.elements.requirement.value);
   const history=head.items.filter(i=>i.requirement===req?.id);
   el.elements.predecessor.innerHTML='<option value="">No predecessor</option>'+history.filter(i=>i.revision<head.revision||['VERIFIED_PASS','VERIFIED_FAIL','SUPERSEDED'].includes(i.state)).map(i=>
    '<option value="'+esc(JSON.stringify({item_id:i.id,revision:i.revision}))+'">'+esc(i.id+' / revision '+i.revision+' / '+i.state+' / budget '+JSON.stringify(i.budget))+'</option>').join('');
   $('#owner-work-context').innerHTML=details({requirement:req||null,status:'UNSATISFIED',
    frontier:history.filter(i=>i.revision===head.revision&&['QUEUED','ACTIVE','WAITING_DEPENDENCY','BLOCKED_REPAIRABLE','WAITING_USER_AUTHORITY'].includes(i.state)).map(i=>i.id),
    history:history.map(i=>({item_id:i.id,revision:i.revision,state:i.state,budget:i.budget,budget_used:i.budget_used})),
    authority_granted:false,accepted:false},'Current criteria and historical allocations').replace('<details>','<details open>');
  };
  el.addEventListener('input',invalidate);el.addEventListener('change',invalidate);
  el.elements.requirement.addEventListener('change',contextFor);
  const requestFor=(preview,command)=>({...preview.intent,command_id:command,preview_hash:preview.preview_hash});
  bindForm('owner-work-form',async f=>{
   if(!active()||committing)return;
   const n=++epoch,intent=identity();displayed=null;commit.disabled=true;
   target.textContent='Loading exact preview…';$('#dialog-error')?.remove();
   try{
    if(!f.command_id.trim())throw Error('Explicit stable command required');
    const request={id:head.id,expected_revision:head.revision,expected_sequence:head.sequence,
     requirement:f.requirement,work_key:f.work_key,rationale:f.rationale,budget:Number(f.budget),
     predecessor:f.predecessor?JSON.parse(f.predecessor):null};
    const preview=await api('objective.work.preview',request);
    if(!current(n,intent))return;
    if(JSON.stringify(preview.intent)!==JSON.stringify(request))throw Error('Preview intent changed; refresh');
    const payload=requestFor(preview,f.command_id),saved=JSON.parse(localStorage.getItem('glacier-owner-work-pending')||'null');
    if(saved?.request.command_id===f.command_id&&JSON.stringify(saved.request)!==JSON.stringify(payload))
     throw Error('Saved command has a different intent; review its exact retry or use a new command.');
    displayed={preview,request:payload,epoch:n,intent};
    show(preview);commit.disabled=!preview.committable;
    if(preview.committable)localStorage.setItem('glacier-owner-work-pending',JSON.stringify({format:'owner-work-v1',preview,request:payload}));
   }catch(e){if(current(n,intent)){target.textContent='ERROR: '+e.message;reportError(e);}}
  });
  commit.onclick=async()=>{
   if(committing||!displayed?.preview.committable||!current(displayed.epoch,displayed.intent)){commit.disabled=true;return;}
   const snapshot=structuredClone(displayed);committing=true;commit.disabled=true;
   try{
    const receipt=await api('objective.work.commit',snapshot.request);
    if(!current(snapshot.epoch,snapshot.intent))return;
    clearObjectiveSelection();displayed=null;show(receipt);
   }catch(e){if(current(snapshot.epoch,snapshot.intent)){show(snapshot.preview);const error=document.createElement('p');error.textContent='ERROR: '+e.message;target.prepend(error);reportError(e);}}
   finally{committing=false;commit.disabled=!(displayed?.preview.committable&&current(displayed.epoch,displayed.intent));}
  };
  $('[data-action=owner-work-retry]').onclick=()=>{
   if(!active()||committing)return;
   invalidate();
   try{
    const saved=JSON.parse(localStorage.getItem('glacier-owner-work-pending')||'null');
    if(saved?.format!=='owner-work-v1'||saved.request.id!==head.id||
       JSON.stringify(requestFor(saved.preview,saved.request.command_id))!==JSON.stringify(saved.request))
     throw Error('Saved work command does not match displayed intent');
    const request=saved.request;
    for(const name of ['requirement','work_key','rationale','budget','command_id'])el.elements[name].value=request[name];
    contextFor();
    if(request.predecessor){
     const option=document.createElement('option');option.value=JSON.stringify(request.predecessor);
     option.textContent='Saved historical identity: '+request.predecessor.item_id;
     el.elements.predecessor.append(option);el.elements.predecessor.value=option.value;
    }
    displayed={preview:saved.preview,request,epoch,intent:identity()};show(saved.preview);
    const note=document.createElement('p');note.textContent='Exact historical retry: returns the original receipt if already committed; grants no renewed authority.';target.prepend(note);
    commit.disabled=!saved.preview.committable;
   }catch(e){target.textContent='ERROR: '+e.message;reportError(e);}
  };
 }catch(e){if(active())reportError(e);}
}

async function openObjectiveSelection(){
 const view=generation,caller=ASSISTANT_ID,context=objectiveCallerIdentity(),routeIdentity=location.hash;
 clearObjectiveSelection();
 const selectionEpoch=objectiveSelectionEpoch;
 modal('Select current work — identity only','<p id="objective-selection-loading">Loading current work…</p>');
 const dialog=$('#dialog'),loading=$('#objective-selection-loading'),listeners=new AbortController();
 let el=null,epoch=0,pending=null,closed=false;
 const active=()=>!closed&&view===generation&&location.hash===routeIdentity&&dialog.open&&
  caller===ASSISTANT_ID&&context===objectiveCallerIdentity()&&selectionEpoch===objectiveSelectionEpoch&&
  (el?el.isConnected&&$('#objective-select-form')===el:loading.isConnected);
 const identity=()=>JSON.stringify(Array.from(new FormData(el).entries()));
 const current=request=>active()&&pending===request&&request.epoch===epoch&&request.intent===identity();
 const invalidate=()=>{
  epoch++;pending=null;objectiveSelection=null;
  if(el?.isConnected){el.querySelector('[type=submit]').disabled=false;$('#objective-selection-detail').textContent='Changed selection; inspect before submitting.';$('#dialog-error')?.remove();}
 };
 const dismiss=()=>{
  closed=true;epoch++;pending=null;listeners.abort();
  // A completed explicit confirmation survives closing its inspector.
  // Outstanding requests have no confirmed selection to preserve.
 };
 for(const event of ['close','cancel','modalreplace'])dialog.addEventListener(event,dismiss,{signal:listeners.signal});
 window.addEventListener('hashchange',dismiss,{signal:listeners.signal});
 try{
  const value=await api('objective.inspect'),head=value.objective;
  if(!active())return;
  const items=head.items.filter(i=>i.revision===head.revision&&['QUEUED','WAITING_DEPENDENCY'].includes(i.state)&&!i.execution_ref&&!i.execution_outcome);
  $('#dialog-body').innerHTML=form('objective-select-form',
   select('item_id','Current pending item',items.map(i=>[i.id,i.requirement+' / '+i.state+' / budget '+JSON.stringify(i.budget)]))+
   '<div id="objective-selection-detail">Selection grants no authority. Fresh owner authorization is required.</div>',
   'Inspect and select');
  el=$('#objective-select-form');
  const target=$('#objective-selection-detail');
  el.addEventListener('input',invalidate,true);el.addEventListener('change',invalidate,true);
  el.onsubmit=async event=>{
   event.preventDefault();
   if(!active())return;
   const f=Object.fromEntries(new FormData(el)),submit=el.querySelector('[type=submit]');
   submit.disabled=true;notify('Executing / objective-select-form');
   const request={epoch:++epoch,intent:identity()};
   pending=request;objectiveSelection=null;target.textContent='Loading exact identity…';$('#dialog-error')?.remove();
   const ref={id:head.id,item_id:f.item_id,revision:head.revision};
   try{
    const selection=await api('objective.selection',ref);
    if(!current(request))return;
    if(JSON.stringify(selection.objective_ref)!==JSON.stringify(ref))throw Error('Selection identity changed; refresh');
    objectiveSelection={caller,context,routeIdentity,intentCurrent:()=>request.intent===identity(),objective_ref:JSON.parse(JSON.stringify(ref))};
    target.innerHTML=details(selection,'Revision, dependencies, budget and evidence gaps').replace('<details>','<details open>');
   }catch(e){
    if(!current(request))return;
    target.textContent='ERROR: '+e.message;reportError(e);
   }finally{if(pending===request){pending=null;if(el.isConnected)submit.disabled=false;}}
  };
 }catch(e){if(active())reportError(e);}
}

const bindOrdinaryPage=bindPage;
bindPage=function(){
 bindOrdinaryPage();
 for(const b of document.querySelectorAll('[data-action=owner-contract],[data-action=objective-select],[data-action=owner-new-work]'))b.onclick=async()=>{
  b.disabled=true;try{await (b.dataset.action==='owner-contract'?openOwnerContract():b.dataset.action==='owner-new-work'?openOwnerNewWork():openObjectiveSelection());}
  catch(e){reportError(e);}finally{if(b.isConnected)b.disabled=false;}
 };
 const actionScope=$('#assistant-action-scope');if(actionScope)for(const event of ['input','change'])actionScope.addEventListener(event,clearObjectiveSelection);
 const assistantSelection=$('#assistant-worker-selection');if(assistantSelection)assistantSelection.onchange=()=>{clearObjectiveSelection();ASSISTANT_ID=assistantSelection.value;localStorage.setItem('glacier-assistant-worker',ASSISTANT_ID);render();};
 const remoteSetup=$('[data-action=assistant-remote-setup]');if(remoteSetup)remoteSetup.onclick=async()=>{remoteSetup.disabled=true;try{const w=await api('assistant.create_remote');ASSISTANT_ID=w.id;localStorage.setItem('glacier-assistant-worker',w.id);await render();notify('Fresh non-local Assistant created. No local history or memory was transferred.');}catch(e){reportError(e);}finally{if(remoteSetup.isConnected)remoteSetup.disabled=false;}};
 const setupAssistant=$('[data-action=assistant-setup]');if(setupAssistant)setupAssistant.onclick=async()=>{setupAssistant.disabled=true;try{if(workers.some(w=>w.id===ASSISTANT_ID))throw Error('Assistant already exists; refresh the page.');await api('worker.save',{worker:ASSISTANT_ID,expected_revision:0,configuration:{id:ASSISTANT_ID,name:'Glacier Assistant',role:'Personal Guide',description:'Persistent local conversational guide to Glacier.',instructions:['You are Glacier Assistant, the user’s local guide to Glacier.','Answer conversationally and clearly. Explain the five areas: Assistant, Projects, Environments, Activity and System.','Do not claim to perform actions or inspect live state unless Glacier has provided that evidence. If unsure, say so instead of guessing.','Respect task objectives, privacy boundaries and all Glacier permissions. Never request credentials.','For direct navigation requests, Glacier handles navigation locally. Your verified runtime is Glacier MAF using local Ollama model llama3.2:3b. Do not invent other runtime details or claim unassigned tools.'],runtime:{provider:'maf_ollama',model:'llama3.2:3b'},execution_policy:{privacy:'LOCAL_ONLY'},permissions:{filesystem:'none',network:false,capabilities:{}},memory:{task:'READ_WRITE',worker:'READ_WRITE',project:'READ',organization:'NONE',on_completion:'KEEP'},context:{fresh_on_task_start:false,reset_on_task_complete:false}}});await render();notify('Glacier Assistant is ready on the local model.');}catch(e){reportError(e);}finally{if(setupAssistant.isConnected)setupAssistant.disabled=false;}};
 bindForm('assistant-action-scope',async f=>{const scope={enabled:f.enabled==='true',privacy:f.privacy,projects:JSON.parse(f.projects),workers:JSON.parse(f.workers),created_worker_prefix:f.prefix,max_commands:Number(f.budget)};await api('assistant.configure',{worker:ASSISTANT_ID,scope,expected_revision:Number(f.revision)});await render();notify('Scoped product actions saved. Shell, approvals and production authority remain unchanged.');});
 for(const button of document.querySelectorAll('[data-action=objective-initialize],[data-action=objective-inspect]'))button.onclick=async()=>{button.disabled=true;try{result(await api(button.dataset.action==='objective-initialize'?'objective.initialize':'objective.inspect'),'Persistent campaign objective');}catch(e){reportError(e);}finally{if(button.isConnected)button.disabled=false;}};
 const ownerEvidence=async(action,params,title,element)=>{const view=generation,target=$('#objective-recovery-outcome');if(target)target.textContent='Reading or recording exact owner evidence…';try{const value=await api(action,params);if(view!==generation||!element.isConnected)return;if(target?.isConnected)target.innerHTML=badge(value.status)+details(value,'Actual owner receipt');result(value,title);}catch(e){if(view===generation&&element.isConnected){if(target?.isConnected)target.textContent='ERROR: '+e.message;reportError(e);}}};
 bindForm('objective-review-preview',async(f,el)=>ownerEvidence('objective.review.preview',f,'Current binding — independent review required',el));
 bindForm('objective-review-ingest',async(f,el)=>ownerEvidence('objective.review.ingest',{...f,expected_sequence:Number(f.expected_sequence)},'Immutable independent review receipt',el));
 bindForm('objective-reject-preview',async(f,el)=>ownerEvidence('objective.review.reject_preview',f,'Historical rejection binding — uncertainty preserved',el));
 bindForm('objective-reject-ingest',async(f,el)=>ownerEvidence('objective.review.reject',{...f,expected_sequence:Number(f.expected_sequence)},'Independent rejection and bounded repair',el));
 bindForm('objective-failure-preview',async(f,el)=>ownerEvidence('objective.failure.preview',f,'Exact terminal failure closure',el));
 bindForm('objective-failure-dispose',async(f,el)=>ownerEvidence('objective.failure.dispose',{...f,expected_sequence:Number(f.expected_sequence)},'Immutable failed history disposition',el));
 bindForm('objective-bind',async f=>{const value=await api('objective.bind',{...f,expected_sequence:Number(f.expected_sequence)});result(value,'Sealed objective execution binding');});
 bindForm('objective-authorize',async f=>{const value=await api('objective.authorize',{...f,expected_sequence:Number(f.expected_sequence)});result(value,'Scoped objective coordinator authorization');});
 const inspectProduct=$('[data-action=assistant-receipts]');if(inspectProduct)inspectProduct.onclick=async()=>{const view=generation,identity=ASSISTANT_ID;inspectProduct.disabled=true;try{const value=await api('assistant.receipts',{worker:identity});if(view===generation&&identity===ASSISTANT_ID)result(value,'Actual Assistant execution receipts');}catch(e){if(view===generation&&identity===ASSISTANT_ID)reportError(e);}finally{if(inspectProduct.isConnected)inspectProduct.disabled=false;}};
 bindForm('assistant-chat',async f=>{if(!f.text.trim())return;const destination=assistantDestination(f.text);if(destination){location.hash=destination;return;}if(objectiveSelection&&(!objectiveSelection.intentCurrent()||objectiveSelection.context!==objectiveCallerIdentity()||objectiveSelection.routeIdentity!==location.hash))clearObjectiveSelection();const selected=objectiveSelection?JSON.parse(JSON.stringify(objectiveSelection)):null,caller=ASSISTANT_ID;
 if(selected&&selected.caller!==caller)throw Error('Assistant identity changed; select current work again');
 const receipt=await api(selected?'assistant.objective.chat':'chat',selected?{worker:caller,text:f.text,objective_ref:selected.objective_ref}:{worker:caller,text:f.text});if(receipt?.status==='FAILED'||receipt?.task?.status==='FAILED'||receipt?.success===false)throw Error(receipt.error||receipt.reason||receipt.error_type||'Assistant turn failed; inspect task diagnostics');await render();$('#assistant-chat [name=text]')?.focus();notify('Assistant replied. Conversation saved in Glacier history.');});
 bindForm('assistant-project-create',async f=>{await api('project.register',f);location.hash='#projects';});
 const presentation=$('#presentation-mode');if(presentation)presentation.onchange=()=>{localStorage.setItem('glacier-presentation',presentation.value);document.documentElement.dataset.presentation=presentation.value;render();};
 const inspectEffects=$('#effects-inspect');if(inspectEffects)inspectEffects.onclick=async()=>{
  const view=generation,target=$('#effects-records'),status=$('#effects-outcome');inspectEffects.disabled=true;status.textContent='Reading UNKNOWN effects…';
  try{const effects=await api('effects',{state:'UNKNOWN',limit:100});if(view!==generation||!target.isConnected)return;if(!Array.isArray(effects))throw Error('Effect inventory unavailable');
   target.innerHTML=effects.length?table(['Receipt','Worker / Task','Capability','State','Evidence'],effects.map(e=>[esc(e.id),esc(e.worker_id)+' / '+esc(e.task_id),esc(e.capability),badge(e.state),details(e,'Actual effect receipt')]))+
    form('effect-reconcile',select('id','Effect receipt',effects.map(e=>[e.id,e.id+' · '+e.worker_id+' · '+e.capability]))+select('state','Recorded outcome',['UNKNOWN','CONFIRMED','FAILED'],'UNKNOWN')+area('evidence','Evidence for this exact receipt (maximum 1000 characters)','','required maxlength="1000"')+'<p class="wide">CONFIRMED: evidence establishes the effect occurred. FAILED: evidence establishes it failed. UNKNOWN: uncertainty remains. Inspect the selected receipt and provide supporting evidence before submitting.</p>','Record reconciliation'):empty('No UNKNOWN effects recorded.');
   status.textContent=effects.length+' UNKNOWN effects loaded. No outcome changed.';
   bindForm('effect-reconcile',async f=>{const formView=generation;if(!f.evidence.trim()||f.evidence.length>1000){status.textContent='ERROR: Evidence must contain 1–1000 characters.';return;}status.textContent='Recording reconciliation…';try{const value=await api('effect.reconcile',f);if(formView===generation&&status.isConnected){status.innerHTML=badge(value.state)+details(value,'Actual reconciliation receipt').replace('<details>','<details open>');$('#effect-reconcile')?.remove();notify('Reconciliation recorded. Inspect effects again to refresh.');}}catch(e){if(formView===generation&&status.isConnected)status.textContent='ERROR: '+e.message;reportError(e);}});
  }catch(e){if(view===generation&&status.isConnected)status.textContent='ERROR: '+e.message;reportError(e);}finally{if(inspectEffects.isConnected)inspectEffects.disabled=false;}
 };
 const outcome=value=>{const target=$('#assistant-outcome');if(target)target.innerHTML=badge(value?.receipt?.state||value?.status||value?.state||'RECORDED')+developmentLinks(value).replace('<details>','<details open>');};
 bindForm('assistant-project',async f=>{const value=await api('project.register',f);await render();outcome(value);notify('Project registration recorded.');});
 bindForm('assistant-bind',async f=>{outcome(await api('project.bind',{...f,expected_revision:Number(f.expected_revision),write_scope:JSON.parse(f.write_scope)}));notify('Workspace binding saved. Authority unchanged.');});
 bindForm('assistant-worker',async f=>{if(workers.some(w=>w.id===f.id))throw Error('Worker already exists; use its existing configuration controls.');const value=await api('worker.save',{worker:f.id,expected_revision:0,configuration:{id:f.id,name:f.name,role:'Developer',instructions:['Work only on the active immutable Blueprint through managed tools.'],capability_project:f.project,runtime:{provider:'maf_ollama',model:'llama3.2:3b'},execution_policy:{privacy:'LOCAL_ONLY'},permissions:{capabilities:{'files.read':'ALLOW','files.write':'ALLOW','shell.execute':'ALLOW'}}}});await render();outcome(value);notify('Operation recorded — inspect the actual receipt below.');});
 bindForm('assistant-create',async f=>{const {routing_mode,routing_pin,...fields}=f;const routing_policy=routing_mode==='AUTO'?{mode:'AUTO'}:routing_mode==='PIN'?{mode:'PIN',pin:routing_pin}:undefined;const value=await api('blueprint.create',{...fields,...(routing_policy?{routing_policy}:{}),include_control_context:f.include_control_context==='true',write_scope:JSON.parse(f.write_scope),verification_command:JSON.parse(f.verification_command),constraints:JSON.parse(f.constraints)});await render();outcome(value);notify('Operation recorded — inspect the actual receipt below.');});
 for(const button of document.querySelectorAll('[data-bp]'))button.onclick=async()=>{const view=generation;button.disabled=true;const target=$('#assistant-outcome');if(target)target.textContent='Executing '+button.dataset.bp+'…';try{const id=button.dataset.id,op=button.dataset.bp;let value;if(op==='execute'){const occurrence=developmentOccurrence(id),b=await api('blueprint.get',{id}),runs=Array.isArray(b?.prepared?.runs)?b.prepared.runs:[],prior=runs.find(r=>r?.occurrence===occurrence);value=prior?{blueprint:b,receipt:prior,duplicate:true}:await api('blueprint.execute',{id,occurrence});}else value=await api('blueprint.'+op,{id});if(view===generation){if(['prepare','reprepare','execute'].includes(button.dataset.bp)){const expected=generation+1;await render();if(generation===expected)outcome(value);}else outcome(value);}}catch(e){if(view===generation&&target)target.textContent='ERROR: '+e.message;reportError(e);}finally{if(button.isConnected)button.disabled=false;}};
};
window.addEventListener('hashchange',()=>{clearObjectiveSelection();render();});appearance();render();

async function assistantActionsHtml(w){
 const inventory=await api('assistant.inventory',{worker:ASSISTANT_ID}),scope=w.configuration.product_access||{enabled:false,projects:[],workers:[],created_worker_prefix:'assistant-created-',max_commands:20};
 return ownerContractPanel()+panel('Actual product actions',`<p>${scope.enabled?'Scoped coordination enabled.':'Product actions are not configured.'} Queued requests are not completed work. Only persisted receipts prove execution.</p>${details(inventory,'Available actions and scope')}${btn('Inspect execution receipts','assistant-receipts',scope.enabled?'':'disabled')}${btn('Initialize persistent objective','objective-initialize')}${btn('Inspect persistent objective','objective-inspect')}<details><summary>Configure scoped actions</summary><p>Owner configuration: existing Projects and workers matching the explicit privacy scope only. New workers start with default-deny permissions. No approvals, permission changes or production apply are exposed.</p>${form('assistant-action-scope',field('revision','Assistant revision',w.revision,'number','readonly')+select('enabled','Scoped actions',['false','true'],String(scope.enabled))+select('privacy','Product privacy scope',['LOCAL_ONLY','ANY'],scope.privacy||'LOCAL_ONLY')+area('projects','Allowed Project IDs (JSON array)',JSON.stringify(scope.projects))+area('workers','Allowed existing worker IDs (JSON array)',JSON.stringify(scope.workers))+field('prefix','New worker ID prefix',scope.created_worker_prefix)+field('budget','Command limit',scope.max_commands,'number','min="1" max="100"'),'Save scoped product actions')}</details>`);
}

function assistantSelector(){const available=workers.filter(w=>w.id==='glacier-assistant'||w.id==='glacier-campaign-assistant'||w.configuration?.product_access?.enabled);return `<div class="toolbar"><label>Assistant identity<select id="assistant-worker-selection">${available.map(w=>`<option value="${esc(w.id)}" ${w.id===ASSISTANT_ID?'selected':''}>${esc(w.name)} / ${esc(w.id)}</option>`).join('')}</select></label>${workers.some(w=>w.id==='glacier-campaign-assistant')?'':btn('Create fresh Codex Assistant','assistant-remote-setup')}<p>Separate identities preserve local-only history. Creating an identity does not run inference or grant tools.</p></div>`;}
